def highlight(self, text: Text) -> None:
    """Highlight :class:`rich.text.Text` using regular expressions.

    Args:
        text (~Text): Text to highlighted.

    """
    if self._is_single_width(text.plain):
        return

    highlight_regex = text.highlight_regex
    for re_highlight in self.highlights:
        highlight_regex(re_highlight, style_prefix=self.base_style)

def _is_single_width(self, text: Text) -> bool:
    """Check if the given text consists only of single-width characters."""
    for char in text.plain:
        code = ord(char)
        is_single = False
        for start, end, width in _cell_widths.CELL_WIDTHS:
            if start <= code <= end and width == 1:
                is_single = True
                break
        if not is_single:
            return False
    return True
